'use strict';
const {Arena,W,H,THEMES,ITEMS,synergy,dist,clamp}=VoidArena;
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),overlay=document.getElementById('overlay');
const game=new Arena(),keys={},pointer={x:600,y:330,down:false};let last=0,lastMode='',touchOrigin=null,touchMove=null,sound=false,audio;
function ellipseOn(ctx,x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function ellipse(...args){ellipseOn(ctx,...args)}
function textOn(ctx,s,x,y,size=12,color='#eee9db',align='left',bold=false){ctx.fillStyle=color;ctx.font=`${bold?'bold ':''}${size}px Arial, sans-serif`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function text(...args){textOn(ctx,...args)}
function tone(f=250,d=.07,type='triangle',v=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),gain=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f/2),audio.currentTime+d);gain.gain.setValueAtTime(v,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(gain);gain.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch(e){}}
function show(html){overlay.innerHTML=html;overlay.classList.remove('hidden')}
function button(id,fn){document.getElementById(id).onclick=()=>{release();fn();canvas.focus();syncOverlay()}}
function syncOverlay(){if(lastMode===game.mode)return;lastMode=game.mode;for(const id of ['jump','tariff'])document.getElementById(id).style.visibility=['play','tutorial'].includes(game.mode)?'visible':'hidden';
if(['play','tutorial','tutorialSuccess','reward','debug'].includes(game.mode)){overlay.classList.add('hidden');return;}
if(game.mode==='menu'){show('<div class="tag">3 ARENAS · ONE MICROPHONE</div><h2>The art of<br><em>the mic.</em></h2><p>Biden → xijinping → Mojtaba Khamenei<br>Swing your mic. Jump to break shields. Use tariffs to control crowds.<br>Clear each arena, then face its boss.<br>Surviving minions keep fighting after the boss falls.</p><button class="primary" id="start">START THE CAMPAIGN ↗</button><div class="hint">WASD MOVE · HOLD CLICK: MELEE · SPACE: JUMP<br>Q: TARIFF · WALK INTO HEALTH KITS<br><br>TOUCH: DRAG + AUTO ATTACK · USE SKILL BUTTONS</div>');button('start',()=>game.start());}
else if(game.mode==='tutorialIntro'){show('<div class="tag">A SHORT SAFE LESSON · SKIPPABLE</div><h2>Break shields.<br><em>Then swing.</em></h2><p>Aim with your mouse. Hold left click for overhead mic swings.<br><b>SPACE</b> Jump to avoid damage. Land nearby to stun and break shields.<br>Normal enemies are stunned for 1.5s; shields break for 3s.<br>Practice: land near the shield dummy, then hit it with your mic.</p><button class="primary" id="practice">PRACTICE JUMP + SWING ↗</button><button class="small tutorials" id="skip">SKIP LESSON</button>');button('practice',()=>game.practice());button('skip',()=>game.skipLesson());}
else if(game.mode==='tutorialDone'){show('<div class="tag">SHIELD BROKEN · MICROPHONE CONNECTED ✓</div><h2>Use the<br><em>opening.</em></h2><p>Jump close → land to break shields → swing your mic.<br>Bosses stagger briefly and resist repeated stuns.<br>After each Boss, walk into the health kit to heal and continue.<br>In chapter 3, red circles warn you before explosions.</p><button class="primary" id="lessonDone">ENTER THE ARENA ↗</button>');button('lessonDone',()=>game.newRun());}
else if(game.mode==='paused'){show('<div class="tag">ARENA PAUSED</div><h2>Hold the<br><em>microphone.</em></h2><p>Combat is paused.</p><button class="primary" id="resume">RESUME ↗</button>');button('resume',()=>game.pause());}
else if(game.mode==='upgrade'){show('<div class="tag">CHAPTER '+game.chapter+' CLEARED · ALL MINIONS CLEARED</div><h2>Build a<br><em>better bad idea.</em></h2><p>Health kit collected. Choose your next item.<br>Next: '+THEMES[game.chapter].name+'</p><div class="choices">'+game.offer.map((u,i)=>{const partner=game.items.find(id=>synergy(id,u.id));return '<button class="choice" id="pick'+i+'"><span>'+u.icon+'</span><b>'+u.name+'</b><small>'+u.desc+'</small>'+(partner?'<small class="synergy">SYNERGY WITH '+ITEMS.find(x=>x.id===partner).name+': '+synergy(partner,u.id)+'</small>':'')+'</button>'}).join('')+'</div>');if(game.offer.length===0){show('<div class="tag">ALL ITEMS COLLECTED</div><h2>Build complete.</h2><p>Health kit collected. Continue to '+THEMES[game.chapter].name+'.</p><button class="primary" id="buildContinue">NEXT CHAPTER ↗</button>');button('buildContinue',()=>game.takeOffer(0));}else game.offer.forEach((_,i)=>button('pick'+i,()=>game.takeOffer(i)));}
else if(['dead','win'].includes(game.mode)){const win=game.mode==='win';show('<div class="tag">'+(win?'THREE BOSSES. NO LOOSE ENDS.':'CAMPAIGN ENDED')+'</div><h2>'+(win?'Victory.<br><em>At what cost?</em>':'Dropped<br><em>the mic.</em>')+'</h2><p>'+(win?'All three bosses and their surviving minions are defeated.':'Keep moving. Mind your melee range. Jump to break shields; use tariffs to control crowds.')+'<br>Score '+game.score+' · '+Math.floor(game.time)+' seconds</p><button class="primary" id="again">RUN IT BACK ↗</button>');button('again',()=>game.newRun());}}
function person(x,y,kind='trump',scale=1,paint=ctx){const ctx=paint,ellipse=(...args)=>ellipseOn(ctx,...args);ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ellipse(0,9,19,7,'#0005');if(kind==='pooh'){ellipse(-11,19,10,6,'#e5ae2d');ellipse(11,19,10,6,'#e5ae2d');ellipse(-22,-8,8,17,'#eebc3c');ellipse(22,-8,8,17,'#eebc3c');ellipse(0,-2,22,25,'#efbe43');ellipse(-4,3,15,17,'#f5c74f');ctx.fillStyle='#cd252a';ctx.beginPath();ctx.moveTo(-14,-29);ctx.lineTo(-26,-21);ctx.lineTo(-23,-9);ctx.lineTo(-17,-11);ctx.lineTo(-18,-1);ctx.quadraticCurveTo(0,4,18,-1);ctx.lineTo(17,-11);ctx.lineTo(23,-9);ctx.lineTo(26,-21);ctx.lineTo(14,-29);ctx.closePath();ctx.fill();ctx.strokeStyle='#a51f22';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-16,-4);ctx.quadraticCurveTo(0,0,16,-4);ctx.stroke();ellipse(-14,-56,8,8,'#eebc3c');ellipse(14,-56,8,8,'#eebc3c');ellipse(-14,-56,4,4,'#dca329');ellipse(14,-56,4,4,'#dca329');ellipse(0,-39,20,21,'#efbd3e');ellipse(0,-29,13,10,'#f6cb58');ellipse(-8,-40,2,2.7,'#302a20');ellipse(8,-40,2,2.7,'#302a20');ellipse(0,-34,4.5,3.2,'#302a20');ctx.strokeStyle='#61431d';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-11,-29);ctx.quadraticCurveTo(0,-18,11,-29);ctx.moveTo(-11,-47);ctx.quadraticCurveTo(-7,-50,-4,-47);ctx.moveTo(4,-47);ctx.quadraticCurveTo(7,-50,11,-47);ctx.stroke();}else if(kind==='mojtaba'){ctx.fillStyle='#242227';ctx.beginPath();ctx.moveTo(-13,-18);ctx.lineTo(-22,15);ctx.lineTo(22,15);ctx.lineTo(13,-18);ctx.fill();ellipse(0,-28,15,18,'#d6a47e');ctx.fillStyle='#343036';ctx.beginPath();ctx.moveTo(-13,-26);ctx.lineTo(-10,-7);ctx.lineTo(0,1);ctx.lineTo(10,-7);ctx.lineTo(13,-26);ctx.fill();ellipse(0,-45,19,10,'#17171c');ellipse(0,-50,14,8,'#25232b');ctx.fillStyle='#10151c';ctx.fillRect(-9,-31,6,3);ctx.fillRect(4,-31,6,3);ctx.strokeStyle='#c5ae8c';ctx.lineWidth=1;ctx.strokeRect(-12,-33,11,7);ctx.strokeRect(2,-33,11,7);}else{ctx.fillStyle='#131927';ctx.fillRect(-12,4,9,12);ctx.fillRect(4,4,9,12);ctx.fillStyle='#eae7dc';ctx.fillRect(-14,-18,28,25);ctx.fillStyle=kind==='xi'?'#283b50':'#294264';ctx.fillRect(-17,-18,12,25);ctx.fillRect(5,-18,12,25);ctx.fillStyle=kind==='biden'?'#80b4ef':'#e55f60';ctx.fillRect(-3,-16,6,20);ctx.fillStyle=kind==='trump'?'#ffa45f':kind==='xi'?'#e9bd99':'#ecc7aa';ctx.fillRect(-14,-39,28,25);ctx.fillRect(-17,-32,5,11);ctx.fillStyle=kind==='trump'?'#ffd671':kind==='biden'?'#edf0ef':'#262d32';ctx.fillRect(-15,-43,30,10);ctx.fillRect(-18,-39,24,7);ctx.fillRect(8,-35,7,6);ctx.fillStyle='#453d38';ctx.fillRect(-9,-29,4,3);ctx.fillRect(6,-29,4,3);if(kind==='biden'){ctx.fillStyle='#273747';ctx.fillRect(-11,-30,11,6);ctx.fillRect(3,-30,11,6);ctx.fillRect(-1,-28,5,2);ctx.fillStyle='#ecc7aa';ctx.fillRect(-12,10,9,11);ctx.fillRect(4,10,9,11);ctx.fillStyle='#f8faf4';ctx.beginPath();ctx.moveTo(-19,-2);ctx.lineTo(19,-2);ctx.lineTo(16,9);ctx.quadraticCurveTo(9,18,0,15);ctx.quadraticCurveTo(-9,18,-16,9);ctx.closePath();ctx.fill();ctx.strokeStyle='#b7cedd';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#d6e8ef';ctx.fillRect(-19,-3,38,5);ctx.fillStyle='#8fbed7';ctx.fillRect(-19,1,7,5);ctx.fillRect(12,1,7,5);ctx.strokeStyle='#c5dce7';ctx.beginPath();ctx.moveTo(-10,7);ctx.quadraticCurveTo(0,13,10,7);ctx.stroke();}ctx.fillStyle='#fff1d1';ctx.fillRect(-2,-20,9,3);}ctx.restore()}
function weaponPose(origin){const swing=game.room.melee.find(s=>s.origin===origin);const face=swing?swing.face:origin.face||0,c=Math.cos(face),d=Math.sin(face),idle={hx:origin.x+c*14,hy:origin.y+d*14-12,tx:origin.x+c*38,ty:origin.y+d*38-12},raised={hx:origin.x+c*10,hy:origin.y+d*10-48,tx:origin.x+c*12,ty:origin.y+d*12-100},impact={hx:origin.x+c*24,hy:origin.y+d*24-10,tx:origin.x+c*76,ty:origin.y+d*76+4};if(!swing)return idle;let a,b,t;if(swing.elapsed<.12){a=idle;b=raised;t=swing.elapsed/.12;}else if(swing.elapsed<.20){a=raised;b=impact;t=(swing.elapsed-.12)/.08;}else{a=impact;b=idle;t=(swing.elapsed-.20)/.22;}t=clamp(t,0,1);return{hx:a.hx+(b.hx-a.hx)*t,hy:a.hy+(b.hy-a.hy)*t,tx:a.tx+(b.tx-a.tx)*t,ty:a.ty+(b.ty-a.ty)*t};}
function downwardMic(origin,height=0){const p=weaponPose(origin),angle=Math.atan2(p.ty-p.hy,p.tx-p.hx),length=Math.hypot(p.tx-p.hx,p.ty-p.hy);ctx.save();ctx.translate(p.hx,p.hy-height);ctx.rotate(angle);ctx.fillStyle='#5d6772';ctx.fillRect(0,-5,length,10);ctx.fillStyle='#c2cdd5';ctx.fillRect(3,-3,Math.max(0,length-7),3);ellipse(length,0,9,12,'#e2eaeb');ctx.strokeStyle='#7e8c96';ctx.lineWidth=1;for(let i=-6;i<=6;i+=3){ctx.beginPath();ctx.moveTo(length-6,i);ctx.lineTo(length+6,i);ctx.stroke();}ctx.restore();}

function drawMob(e,paint=ctx,chapter=game.chapter){const ctx=paint,ellipse=(...args)=>ellipseOn(ctx,...args),text=(...args)=>textOn(ctx,...args);ctx.save();ctx.translate(e.x,e.y);ellipse(0,e.r*.65,e.r*.9,e.r*.35,'#0005');ctx.translate(0,Math.sin(e.age*7)*2);const color=e.flash>0?'#fffbe2':e.color;if(e.type==='charger'){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,-24);ctx.lineTo(24,15);ctx.lineTo(-24,15);ctx.fill();if(e.t<.5&&e.charge<=0){ctx.save();ctx.rotate(e.face);ctx.strokeStyle='#ffc19e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(28,0);ctx.lineTo(65,0);ctx.moveTo(55,-8);ctx.lineTo(65,0);ctx.lineTo(55,8);ctx.stroke();ctx.restore();}}else if(e.type==='turret'){ctx.fillStyle='#685779';ctx.fillRect(-23,5,46,13);ellipse(0,-4,19,19,color);ctx.save();ctx.rotate(e.face);ctx.fillStyle='#e5cbfa';ctx.fillRect(0,-5,29,10);ctx.restore();}else{ellipse(0,-3,e.r,e.r,color);ctx.fillStyle=color;ctx.fillRect(-e.r,-21,7,16);ctx.fillRect(e.r-7,-21,7,16);if(e.type==='splitter'){ctx.strokeStyle='#ad626d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,-20);ctx.lineTo(4,-7);ctx.lineTo(-5,4);ctx.lineTo(2,15);ctx.stroke();}}ellipse(-e.r*.36,-7,4,5,'#30253a');ellipse(e.r*.36,-7,4,5,'#30253a');if(chapter===3&&e.type==='shooter'){ctx.strokeStyle='#dbc2e0';ctx.lineWidth=3;for(const k of [-1,1]){ctx.beginPath();ctx.moveTo(k*12,-8);ctx.lineTo(k*30,-18);ctx.stroke();ellipse(k*30,-18,12,3,'#dbc2e0')}}if(e.type==='shield'&&e.broken<=0){ctx.strokeStyle='#b1eef5';ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,0,e.r+5,e.face-1.25,e.face+1.25);ctx.stroke();}if(e.type==='shield'&&e.broken>0)text('SHIELD BROKEN '+e.broken.toFixed(1)+'s',0,-e.r-37,10,'#d9fb76','center',true);if(e.stun>0)text('✧',0,-e.r-14,21,'#fff0a3','center');if(e.tax>0)text('↓ TAXED',0,-e.r-24,10,'#ffdf8d','center',true);ctx.restore();if(e.hp<e.maxhp){ctx.fillStyle='#171725';ctx.fillRect(e.x-18,e.y+e.r+9,36,4);ctx.fillStyle='#d9fb76';ctx.fillRect(e.x-18,e.y+e.r+9,36*Math.max(0,e.hp/e.maxhp),4)}}
function drawBoss(){const b=game.boss;if(!b||b.dead)return;ctx.save();if(b.flash>0){ctx.shadowColor='#fff1bb';ctx.shadowBlur=18;}person(b.x,b.y,['biden','pooh','mojtaba'][game.chapter-1],1.65);ctx.restore();if(b.grace>0)text('GET READY',b.x,b.y-90,12,'#ffcc9f','center',true);if(b.tax>0)text('↓ TAXED',b.x,b.y+55,12,'#ffde8b','center');}


function draw(){const g=game,r=g.room,p=g.player,theme=g.theme;ctx.clearRect(0,0,W,H);ctx.fillStyle=theme.floor;ctx.fillRect(0,0,W,H);ctx.strokeStyle=theme.grid;ctx.lineWidth=1;for(let x=32;x<W;x+=32){ctx.beginPath();ctx.moveTo(x,78);ctx.lineTo(x,H-28);ctx.stroke();}for(let y=80;y<H;y+=32){ctx.beginPath();ctx.moveTo(28,y);ctx.lineTo(W-28,y);ctx.stroke();}ctx.strokeStyle='#a8ac8366';ctx.lineWidth=3;ctx.strokeRect(28,78,W-56,H-106);
if(g.chapter===2)for(const y of [152,456]){ctx.fillStyle='#17231e';ctx.fillRect(45,y,870,48);ctx.strokeStyle='#7d9578';ctx.lineWidth=2;for(let x=60;x<900;x+=45){const xx=x+(g.time*30%45)*(y<300?1:-1);ctx.beginPath();ctx.moveTo(xx,y+12);ctx.lineTo(xx+(y<300?12:-12),y+24);ctx.lineTo(xx,y+36);ctx.stroke();}}
for(const pool of r.puddles){ellipse(pool.x,pool.y,pool.r,pool.r*.62,'#9c805075');text('SLOW',pool.x,pool.y+4,9,'#d8c69a','center');}
const pickup=r.pickup;if(pickup&&!pickup.used){ctx.fillStyle='#e5eddf';ctx.fillRect(pickup.x-22,pickup.y-22,44,36);ctx.fillStyle='#699476';ctx.fillRect(pickup.x-10,pickup.y-27,20,5);ctx.fillStyle='#d75f63';ctx.fillRect(pickup.x-4,pickup.y-15,8,22);ctx.fillRect(pickup.x-11,pickup.y-8,22,8);text('HEAL +2 / CONTINUE',pickup.x,pickup.y+32,12,'#e8f5db','center',true);}
for(const z of r.fields){ellipse(z.x,z.y,z.r,z.r,'#f7d77d17');ctx.strokeStyle=z.main?'#f7d782':'#d9fb76';ctx.lineWidth=2;ctx.setLineDash([10,7]);ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);text((z.main?'TARIFF':'LANDING')+' '+z.life.toFixed(1)+'s',z.x,z.y-z.r+20,11,'#ffe9ab','center',true);}
for(const h of r.hazards){ellipse(h.x,h.y,h.r,h.r,h.done?'#ffb97566':'#ff725020');ctx.strokeStyle=h.kind==='container'?'#e8cf7b':'#ffa07d';ctx.lineWidth=2;ctx.beginPath();ctx.arc(h.x,h.y,h.r*(h.done?1:clamp(1-h.t/h.max,.05,1)),0,Math.PI*2);ctx.stroke();if(!h.done){if(h.kind==='container')ctx.strokeRect(h.x-28,h.y-28,56,56);text((h.kind==='barrel'?'BARREL':h.kind==='container'?'CONTAINER':h.kind==='stamp'?'TARIFF':'!')+' '+Math.max(0,h.t).toFixed(1),h.x,h.y+4,11,'#ffe1a4','center',true);}}
for(const b of r.bullets){if(b.kind==='urine'){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));ellipse(0,0,b.r,b.r*.7,'#f7d84d');ellipse(2,-2,b.r*.35,b.r*.22,'#fff4b0');ellipse(-b.r-3,0,2,2,'#e7c446');ctx.restore();}else if(b.kind==='homingPoop'){ellipse(b.x,b.y+5,b.r,b.r*.5,'#795039');ellipse(b.x-2,b.y,b.r*.78,b.r*.6,'#966441');ellipse(b.x+1,b.y-6,b.r*.5,b.r*.45,'#ad7c50');ellipse(b.x+2,b.y-10,b.r*.22,b.r*.25,'#c29464');}else{ellipse(b.x,b.y,b.r+3,b.r+3,'#ff7e9725');ellipse(b.x,b.y,b.r,b.r,'#ff97b0');ellipse(b.x-1,b.y-1,2,2,'#ffe8dc');}}
for(const s of r.shots){const a=Math.atan2(s.vy,s.vx);ctx.save();ctx.translate(s.x,s.y);ctx.rotate(a);ctx.strokeStyle=s.kind==='shard'?'#ffafc5':s.kind==='echo'?'#9ff7d1':s.kind==='clone'?'#d4b1ff':'#fff0a5';ctx.lineWidth=3;if(s.kind==='shard'){ctx.beginPath();ctx.moveTo(-7,0);ctx.lineTo(6,0);ctx.stroke();}else for(const radius of [10,17]){ctx.beginPath();ctx.arc(-5,0,radius,-.9,.9);ctx.stroke();}ctx.restore();}
for(const c of r.clones){ctx.save();ctx.globalAlpha=.4;person(c.x,c.y);downwardMic(c,0);ctx.restore();text('CROSSFIRE '+c.life.toFixed(1)+'s',c.x,c.y+30,10,'#d5bbff','center');}
for(const e of r.mobs)if(e.hp>0)drawMob(e);drawBoss();
if(p.jump>0){ellipse(p.x,p.y,65,65,'#d9fb7615');ctx.strokeStyle='#d9fb76aa';ctx.setLineDash([5,5]);ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,65,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);}const jumpHeight=Math.sin(p.jump/.58*Math.PI)*34;if(p.inv<=0||Math.floor(p.inv*14)%2===0||g.mode.startsWith('tutorial')){person(p.x,p.y-jumpHeight);downwardMic(p,jumpHeight);}
for(const s of r.swings){ctx.save();ctx.globalAlpha=s.life/s.max;const x=s.x+Math.cos(s.face)*70,y=s.y+Math.sin(s.face)*70;ellipse(x,y,27,12,s.clone?'#c9aaff35':'#ffe79935');ctx.strokeStyle=s.clone?'#d3b3ff':'#ffefb5';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-12,y-6);ctx.lineTo(x+12,y+6);ctx.moveTo(x-12,y+6);ctx.lineTo(x+12,y-6);ctx.stroke();ctx.restore();}
for(const e of r.effects){ctx.save();ctx.globalAlpha=e.life/e.max;if(e.splash){for(let i=0;i<7;i++){const a=i*Math.PI*2/7,d=e.r*(1-e.life/e.max);ellipse(e.x+Math.cos(a)*d,e.y+Math.sin(a)*d,2.5,2,e.color);}ctx.restore();continue;}ctx.strokeStyle=e.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(e.x,e.y,e.r*(1-e.life/e.max),0,Math.PI*2);ctx.stroke();ctx.lineWidth=1;ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,Math.PI*2);ctx.stroke();ctx.restore();}for(const l of r.labels){ctx.save();ctx.globalAlpha=clamp(l.life*2,0,1);text(l.text,l.x,l.y,12,l.color,'center',true);ctx.restore();}
if(g.debugInvincible){ctx.fillStyle='#263d25ee';ctx.fillRect(28,78,216,24);text('DEBUG · INVINCIBLE',40,95,12,'#d9fb76','left',true);}ctx.fillStyle='#151d26';ctx.fillRect(0,0,W,72);text('0'+g.chapter+' / '+theme.name,36,28,15,theme.accent,'left',true);text('ARENA / '+(g.mode==='reward'?'CLEAR · COLLECT HEALTH KIT':g.boss?'BOSS FIGHT · MINIONS: '+g.remaining():'WAVE: '+g.spawned+'/'+g.waveTotal+' SPAWNED'),36,52,12,'#d1d8c5');text('DIRECTIONAL OVERHEAD MELEE',925,29,11,'#e5e5bf','right',true);text('MOUSE AIM · CLICK SWING · SPACE JUMP · Q TARIFF',925,51,11,'#aab89f','right');
const boss=g.boss;if(boss){ctx.fillStyle='#12151f';ctx.fillRect(182,H-23,596,11);ctx.fillStyle=theme.accent;ctx.fillRect(182,H-23,596*Math.max(0,boss.hp/boss.maxhp),11);ctx.strokeStyle='#292d34';for(const n of [.5]){ctx.beginPath();ctx.moveTo(182+596*n,H-23);ctx.lineTo(182+596*n,H-12);ctx.stroke();}text(g.mode==='reward'?'WALK INTO THE HEALTH KIT':boss.dead?'BOSS DOWN · ENEMIES LEFT: '+g.remaining():boss.name+(boss.hp<boss.maxhp*.5?' / ENRAGED':''),480,H-30,11,boss.dead?'#d9fb76':theme.accent,'center',true);}

if(g.messageTime>0&&g.mode==='play'){ctx.fillStyle='#14202ade';ctx.fillRect(180,103,600,40);text(g.message,480,129,15,theme.accent,'center',true);}const prompt=g.prompt();if(prompt&&['play','reward'].includes(g.mode)){ctx.fillStyle='#142019ed';ctx.fillRect(215,520,530,31);text(prompt,480,541,14,'#e9ffc0','center',true);}
if(['tutorial','tutorialSuccess'].includes(g.mode)){ctx.fillStyle='#14202aee';ctx.fillRect(130,104,700,65);const msg=g.mode==='tutorialSuccess'?'HIT! Jump → break shield → swing.':g.lessonStage==='attack'?'Shield broken! Aim at the dummy and hold left click.':'Press SPACE / JUMP and land close to the dummy.';text(msg,480,131,18,'#d9fb76','center',true);text('Safe dummy · Swing hits a forward arc · Dashed circle shows landing range',480,155,13,'#d5dfcd','center');}
if(g.mode==='play'&&!touchMove){ctx.strokeStyle='#f8e8baa0';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(pointer.x,pointer.y,7,0,Math.PI*2);ctx.moveTo(pointer.x-12,pointer.y);ctx.lineTo(pointer.x+12,pointer.y);ctx.moveTo(pointer.x,pointer.y-12);ctx.lineTo(pointer.x,pointer.y+12);ctx.stroke();}}
function hud(){const p=game.player;document.getElementById('debug-status').hidden=!game.debugInvincible;document.getElementById('health').textContent=game.debugInvincible?'∞ HEARTS':'♥ '.repeat(Math.max(0,p.hp))+'♡ '.repeat(Math.max(0,p.maxhp-p.hp));document.getElementById('jumptext').textContent=p.jumpCd>0?p.jumpCd.toFixed(1)+'s':'READY';document.getElementById('jumpmeter').style.width=(1-p.jumpCd/1.5)*100+'%';const main=game.room.fields.find(z=>z.main);document.getElementById('tarifftext').textContent=main?'ACTIVE '+main.life.toFixed(1)+'s':p.tariffCd>0?p.tariffCd.toFixed(1)+'s':'READY';document.getElementById('tariffmeter').style.width=(1-p.tariffCd/12)*100+'%';document.getElementById('wave').textContent=game.chapter+' / 3';document.getElementById('score').textContent=String(game.score).padStart(4,'0');document.getElementById('weapon').textContent='MELEE MICROPHONE';document.getElementById('build').innerHTML='<b>🎙 Melee Microphone</b><div class="builddesc">Aim with your mouse. Hold click to swing. Jump and land to break shields.</div>'+game.items.map(id=>{const u=ITEMS.find(u=>u.id===id);return'<b>'+u.icon+' '+u.name+'</b><div class="builddesc">'+u.desc+'</div>'}).join('')+(game.items.length===2&&synergy(...game.items)?'<div class="buildsynergy">SYNERGY: '+synergy(...game.items)+'</div>':'');document.getElementById('mission').textContent=game.mode==='reward'?'Arena clear! Walk into the health kit to heal and continue.':game.boss?.dead?'Boss down. Enemies left: '+game.remaining():game.messageTime>0?game.message:'Jump to break shields. Use tariffs for control. Mind your melee range.';}
function release(){pointer.down=false;touchOrigin=null;touchMove=null}
function coords(e){const b=canvas.getBoundingClientRect();return{x:(e.clientX-b.left)*W/b.width,y:(e.clientY-b.top)*H/b.height}}
canvas.addEventListener('pointerdown',e=>{if(!['play','tutorial','reward'].includes(game.mode))return;canvas.setPointerCapture(e.pointerId);const p=coords(e);pointer.x=p.x;pointer.y=p.y;if(e.pointerType==='touch'){touchOrigin=p;touchMove={x:0,y:0};}else pointer.down=true;});canvas.addEventListener('pointermove',e=>{const p=coords(e);pointer.x=p.x;pointer.y=p.y;if(e.pointerType==='touch'&&touchOrigin)touchMove={x:clamp((p.x-touchOrigin.x)/60,-1,1),y:clamp((p.y-touchOrigin.y)/60,-1,1)};});canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('pointerup',e=>{if(e.target===canvas||e.pointerType!=='touch')release()});
window.addEventListener('keydown',e=>{if(debugPanel.isOpen()){if(e.key==='Escape'){e.preventDefault();debugPanel.close();}return;}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.repeat)return;if(e.code==='Space')game.jump();if(e.key.toLowerCase()==='q')game.tariff();if(e.key.toLowerCase()==='p'||e.key==='Escape'){release();game.pause();syncOverlay();}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);function blur(){for(const k of Object.keys(keys))keys[k]=false;release();if(['play','reward'].includes(game.mode))game.pause();syncOverlay();}window.addEventListener('blur',blur);document.addEventListener('visibilitychange',()=>{if(document.hidden)blur()});
for(const [id,fn]of [['jump',()=>game.jump()],['tariff',()=>game.tariff()]])document.getElementById(id).onpointerdown=e=>{e.preventDefault();fn();};document.getElementById('pause').onclick=()=>{release();game.pause();syncOverlay()};document.getElementById('restart').onclick=()=>{release();game.newRun();syncOverlay()};document.getElementById('sound').onclick=()=>{sound=!sound;document.getElementById('sound').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';tone(500)};
function loop(t){const dt=Math.min(.033,Math.max(0,(t-last)/1000));last=t;const input={mx:touchMove?touchMove.x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my:touchMove?touchMove.y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),aim:pointer,attack:pointer.down||!!touchMove,autoAim:!!touchMove};game.step(dt,input);syncOverlay();hud();draw();for(const e of game.events.splice(0)){if(e==='swing')tone(160,.065,'triangle',.018);if(e==='hurt')tone(90,.2,'sawtooth');if(e==='jump')tone(400,.12,'sine');if(e==='tariff')tone(600,.25);if(e==='bossdead')tone(600,.45);if(e==='phase')tone(310,.2);}requestAnimationFrame(loop);}
const debugPanel=createDebugCodex({game,releaseInput(){release();for(const k of Object.keys(keys))keys[k]=false;},syncOverlay,hud,drawEnemy:(e,c)=>drawMob(e,c,3),drawPerson:(kind,c)=>person(70,86,kind,1.25,c)});
syncOverlay();hud();draw();requestAnimationFrame(loop);
